18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "locality", expression = "java(locality(owner))")
25	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
27	    @Mapping(target = "membershipLevel",
28	            expression = "java(org.springframework.samples.petclinic.mapper.OwnerMapper.membershipLevel(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
30	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    /**
34	     * The owner's derived {@code identityKey} = normalizedTelephone + '|' + (email or empty) + '|' +
35	     * householdId, the single key all duplicate detection is expressed through.
36	     */
37	    default String identityKey(Owner owner) {
38	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(
39	                owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
40	    }
41	
42	    /**
43	     * The owner's preferred contact channel: {@code EMAIL} when an email is present, otherwise
44	     * {@code PHONE}.
45	     */
46	    default String contactPreference(Owner owner) {
47	        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
48	    }
49	
50	    default String initials(Owner owner) {
51	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
52	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
53	    }
54	
55	    /**
56	     * The owner's locality (region), read from the REGION component of the customerCode
57	     * ({@code <REGION>-<HASH8>}); see
58	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion#regionOf}.
59	     */
60	    default String locality(Owner owner) {
61	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.regionOf(
62	                owner.getCustomerCode());
63	    }
64	
65	    /**
66	     * A single Luhn check digit (0-9) computed over the digits of the owner's {@code customerCode}.
67	     * Null when the customer code is absent.
68	     */
69	    default Integer checkDigit(Owner owner) {
70	        if (owner.getCustomerCode() == null) {
71	            return null;
72	        }
73	        String code = owner.getCustomerCode();
74	        int sum = 0;
75	        boolean dbl = true;
76	        for (int i = code.length() - 1; i >= 0; i--) {
77	            char c = code.charAt(i);
78	            if (c < '0' || c > '9') {
79	                continue;
80	            }
81	            int d = c - '0';
82	            if (dbl) {
83	                d *= 2;
84	                if (d > 9) {
85	                    d -= 9;
86	                }
87	            }
88	            sum += d;
89	            dbl = !dbl;
90	        }
91	        return (10 - (sum % 10)) % 10;
92	    }
93	
94	    /**
95	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the last two
96	     * digits of the registrationDate year (e.g. {@code NSW-1A2B3C4D-M26}). Null when either the customer
97	     * code or the registration date is absent.
98	     */
99	    default String membershipNumber(Owner owner) {
100	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
101	            return null;
102	        }
103	        return String.format("%s-M%02d", owner.getCustomerCode(),
104	                owner.getRegistrationDate().getYear() % 100);
105	    }
106	
107	    /**
108	     * The owner's membership level, a number from 1 to 3 assigned on creation. Starts at 1; add 1
109	     * when an email is present; add 1 when the owner's name was unique on creation (namesakeCount is
110	     * 0); capped at 3. Level 4 is reserved for tenure.
111	     */
112	    static int membershipLevel(Owner owner) {
113	        int level = 1;
114	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
115	        if (hasEmail) {
116	            level++;
117	        }
118	        Integer namesakeCount = owner.getNamesakeCount();
119	        if (namesakeCount != null && namesakeCount == 0) {
120	            level++;
121	        }
122	        return Math.min(level, 3);
123	    }
124	
125	    Owner toOwner(OwnerDto ownerDto);
126	
127	    @Mapping(target = "id", ignore = true)
128	    @Mapping(target = "pets", ignore = true)
129	    Owner toOwner(OwnerFieldsDto ownerDto);
130	
131	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
132	
133	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
134	
135	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
136	        OwnerPageDto ownerPageDto = new OwnerPageDto();
137	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
138	        ownerPageDto.setPage(ownerPage.getNumber());
139	        ownerPageDto.setSize(ownerPage.getSize());
140	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
